        checkNegatingIfNegativeConstantAAlternating(127, 1)
    }

    @inline(__always)
    private func checkLeadingZeroBitCountWhereConstantMask(_ mask: H.Mask) {
        let mismatches = Mismatches("leadingZeroBitCountWhere with mask \(describe(mask))")
        let aInputs = Inputs.vectors(H.self, seed: 0x7F00_B078_0DAD_94B9)
        for a in aInputs {
            mismatches.check(
                H.leadingZeroBitCount(a, where: mask),
                H(raw: HighwayReference.leadingZeroBitCountWhereI16(mask.raw, a.raw)),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }

    @Test func leadingZeroBitCountWhereConstantMaskAllFalse() {
        checkLeadingZeroBitCountWhereConstantMask(H.Mask(H.Mask.SIMDType(repeating: false)))
    }

    @Test func leadingZeroBitCountWhereConstantMaskAllTrue() {
        checkLeadingZeroBitCountWhereConstantMask(H.Mask(H.Mask.SIMDType(repeating: true)))
    }

    @Test func leadingZeroBitCountWhereConstantMaskOnlyFirst() {
        checkLeadingZeroBitCountWhereConstantMask(
            {
                var simd = H.Mask.SIMDType(repeating: false)
                simd[0] = true
                return H.Mask(simd)
            }()
        )
    }

    @Test func leadingZeroBitCountWhereConstantMaskOnlyLast() {
        checkLeadingZeroBitCountWhereConstantMask(
            {
                var simd = H.Mask.SIMDType(repeating: false)
                simd[H.laneCount - 1] = true
                return H.Mask(simd)
            }()
        )
    }

    @Test func leadingZeroBitCountWhereConstantMaskAllButFirst() {
        checkLeadingZeroBitCountWhereConstantMask(
            {
                var simd = H.Mask.SIMDType(repeating: true)
                simd[0] = false
                return H.Mask(simd)
            }()
        )
    }

    @Test func leadingZeroBitCountWhereConstantMaskAllButLast() {
        checkLeadingZeroBitCountWhereConstantMask(
            {
                var simd = H.Mask.SIMDType(repeating: true)
                simd[H.laneCount - 1] = false
                return H.Mask(simd)
            }()
        )
    }
